import React from "react";
import { useTranslation } from "react-i18next";
import { navigate } from "gatsby";
import { useLocation } from "@reach/router";

interface ButtonProps {
  isDisabled: boolean;
  isSubmit?: boolean;
  sending?: boolean;
}

const ButtonComponent = ({ isDisabled, isSubmit = false, sending = false }: ButtonProps) => {
  const { t } = useTranslation();
  const location = useLocation();

  const handleClick = () => {
    if (!isSubmit) {
      navigate("/contact");
    }
  };

  const isContactPage = location.pathname.startsWith("/contact");

  return (
    <button
      type={isSubmit ? "submit" : "button"}
      onClick={handleClick}
      disabled={isDisabled}
      className={`
        ${isDisabled ? "opacity-20 cursor-not-allowed" : ""}
        w-full border 
        !backdrop-blur-md 
        rounded-full py-4 px-4 body-4
        border-Tofu hover:border-Oatmeal 
        bg-white/10 hover:bg-white/20 
        active:border-DeepSea active:text-DeepSea
      `}
    >
      {isContactPage
        ? sending
          ? t("contact.form.sending")
          : t("contact.form.send")
        : t("home.cta.button")}
    </button>
  );
};

export default ButtonComponent;
