import React, { useState, useRef } from "react";
import { motion, AnimatePresence } from "framer-motion";
import { useTranslation } from "react-i18next";
import imagesProducts from "../images/products";
import data from "../data/data.json";
import CarouselArrow from "./carouselArrow";
import PlusIcon from "./plusIcon";

type ProductImage = { imageDesktop?: string; imageMobile?: string };
type TextItem = { item?: string; subtitle?: string; items?: { item: string }[] };
type Spec = { item?: string; subtitle?: string; };

type SectionKey = "about" | "features" | "applications" | "specifications";

const SECTIONS: { key: SectionKey; label: string }[] = [
  { key: "about", label: "About This Product" },
  { key: "features", label: "Key Features & Benefits" },
  { key: "applications", label: "Recommended Applications" },
  { key: "specifications", label: "Product Specifications" },
];

const EASE: [number, number, number, number] = [0.25, 0.46, 0.45, 0.94];

const contentVariants = {
  open: { height: "auto", opacity: 1, transition: { duration: 0.45, ease: EASE } },
  closed: { height: 0, opacity: 0, transition: { duration: 0.35, ease: EASE } },
};

const imageVariants = {
  enter: { opacity: 0 },
  center: { opacity: 1, transition: { duration: 0.35, ease: EASE } },
  exit: { opacity: 0, transition: { duration: 0.25, ease: EASE } },
};

interface ProductDisplayProps {
  translationKey?: string;
  submenuItems?: string[];
}

const ProductDisplay = ({ translationKey = "products", submenuItems }: ProductDisplayProps) => {
  const { t } = useTranslation();
  const categories = (t(`${translationKey}.items`, { returnObjects: true }) as Array<any>) || [];

  const [imageIndexes, setImageIndexes] = useState<Record<string | number, number>>({});
  const [openSections, setOpenSections] = useState<Record<string | number, SectionKey>>({});
  const [containerHeights, setContainerHeights] = useState<Record<string | number, number>>({});
  const touchStartX = useRef<number | null>(null);
  const containerRefs = useRef<Record<string | number, HTMLDivElement | null>>({});

  const getImageIndex = (id: string | number) => imageIndexes[id] ?? 0;
  const getOpenSection = (id: string | number): SectionKey => openSections[id] ?? "about";

  const handlePrev = (id: string | number, total: number) =>
    setImageIndexes(prev => ({ ...prev, [id]: ((prev[id] ?? 0) - 1 + total) % total }));

  const handleNext = (id: string | number, total: number) =>
    setImageIndexes(prev => ({ ...prev, [id]: ((prev[id] ?? 0) + 1) % total }));

  const handleTouchStart = (e: React.TouchEvent) => {
    touchStartX.current = e.touches[0].clientX;
  };

  const handleTouchEnd = (e: React.TouchEvent, id: string | number, total: number) => {
    if (touchStartX.current === null) return;
    const delta = touchStartX.current - e.changedTouches[0].clientX;
    if (Math.abs(delta) > 40) {
      delta > 0 ? handleNext(id, total) : handlePrev(id, total);
    }
    touchStartX.current = null;
  };

  const handleSection = (id: string | number, key: SectionKey) =>
    setOpenSections(prev => ({ ...prev, [id]: key }));

  return (
    <section className="text-DeepSea">
      {categories.map((category, catIndex) => (
        <div key={catIndex} className="" id={submenuItems ? submenuItems[catIndex] : data.submenuProducts[catIndex]}>
          {category.products?.map((product: any) => {
            const productId = product.id;
            const images: ProductImage[] = (product.imageProduct || []).filter(
              (img: ProductImage) => img.imageDesktop
            );
            const currentIdx = getImageIndex(productId);
            const openSection = getOpenSection(productId);

            const currentImg = images[currentIdx];
            const desktopKey = currentImg?.imageDesktop ?? "";
            const mobileKey = currentImg?.imageMobile ?? desktopKey;
            const desktopData = desktopKey ? imagesProducts[desktopKey] : null;
            const mobileData = mobileKey ? imagesProducts[mobileKey] : desktopData;

            const [productHead, ...subtitleParts] = product.name.split(/\s[-–]\s/);
            const productSubtitle = subtitleParts.join(" - ");

            const aboutContent: TextItem[] = product.aside?.intro || [];
            const featuresContent: TextItem[] = [
              ...(product.aside?.keyFeatures || []),
              ...(product.aside?.keyBenefits || []),
            ];
            const applicationsContent: TextItem[] = product.aside?.applications || [];
            const specsContent: Spec[] = product.aside?.specifications || [];

            const getSectionContent = (key: SectionKey): TextItem[] | Spec[] => {
              switch (key) {
                case "about":
                  return aboutContent.filter(i => i.item || i.subtitle);
                case "features":
                  return featuresContent.filter(i => i.item || i.subtitle);
                case "applications":
                  return applicationsContent.filter(i => i.item || i.subtitle);
                case "specifications":
                  return specsContent;
              }
            };

            return (
              <div
                key={productId}
                className="relative py-12 first:pb-24 sm:first:pb-12 after:content-[''] after:absolute after:bottom-0 after:left-1/2 after:-translate-x-1/2 after:w-[calc(100vw-2.5rem)] after:h-[0.5px] after:bg-DeepSea sm:after:content-none sm:border-b-[0.5px] sm:border-DeepSea first:before:content-[''] first:before:absolute first:before:top-0 first:before:left-1/2 first:before:-translate-x-1/2 first:before:w-[calc(100vw-2.5rem)] first:before:h-[0.5px] first:before:bg-DeepSea sm:first:before:content-none"
              >
                <div className="w-full">
                  <img
                    src={`/${product.iconDivision}.svg`}
                    alt={product.iconDivision}
                    className="h-[30px] sm:h-[42px] mx-5 sm:mx-0"
                  />
                  <h2 className="head-3 sm:head-2 text-DeepSea pt-8 pb-2 uppercase mx-5 sm:mx-0">
                    {productHead}
                  </h2>
                  {productSubtitle && (
                    <p className="head-6 sm:body-1 text-DeepSea mb-8 mx-5 sm:mx-0">{productSubtitle}</p>
                  )}                  
                </div>

                <div className="flex flex-col sm:flex-row w-full">
                  {/* LEFT — image carousel */}
                  <div className="w-full sm:w-1/2 max-w-auto sm:max-w-[825px]">
                    <div className="relative select-none">
                      {/* Image */}
                      <div
                        ref={el => { containerRefs.current[productId] = el; }}
                        className="relative overflow-hidden max-h-auto sm:max-h-[749px]"
                        style={{ minHeight: containerHeights[productId] ?? undefined }}
                        onTouchStart={handleTouchStart}
                        onTouchEnd={e => images.length > 1 && handleTouchEnd(e, productId, images.length)}
                      >
                        <AnimatePresence mode="wait">
                          {desktopData && (
                            <motion.div
                              key={`${productId}-${currentIdx}`}
                              variants={imageVariants}
                              initial="enter"
                              animate="center"
                              exit="exit"
                            >
                              {/* Mobile image */}
                              {mobileData && mobileData !== desktopData && (
                                <img
                                  src={mobileData.src}
                                  alt={mobileData.alt || product.name}
                                  className="sm:hidden w-full h-auto object-contain"
                                />
                              )}
                              {/* Desktop image */}
                              <img
                                src={desktopData.src}
                                alt={desktopData.alt || product.name}
                                className={`${mobileData && mobileData !== desktopData ? "hidden sm:block" : ""} w-full max-h-auto sm:max-h-[749px] h-auto object-contain`}
                                onLoad={() => {
                                  const h = containerRefs.current[productId]?.offsetHeight;
                                  if (h) setContainerHeights(prev => ({ ...prev, [productId]: h }));
                                }}
                              />
                            </motion.div>
                          )}
                        </AnimatePresence>

                        {/* Prev / Next arrows */}
                        {images.length > 1 && (
                          <>
                            <CarouselArrow direction="prev" onClick={() => handlePrev(productId, images.length)} className="-ml-1 sm:ml-2" />
                            <CarouselArrow direction="next" onClick={() => handleNext(productId, images.length)} className="-mr-1 sm:mr-2" />
                          </>
                        )}
                      </div>

                      {/* Dots */}
                      {images.length > 1 && (
                        <div className="flex justify-center gap-2 mt-6">
                          {images.map((_, idx) => (
                            <button
                              key={idx}
                              aria-label={`Go to image ${idx + 1}`}
                              onClick={() => setImageIndexes(prev => ({ ...prev, [productId]: idx }))}
                              className={`w-2 h-2 rounded-full transition-all duration-300 ${
                                idx === currentIdx ? "bg-DeepSea scale-125" : "bg-DeepSea/30"
                              }`}
                            />
                          ))}
                        </div>
                      )}
                    </div>
                  </div>

                  {/* RIGHT — collapsible sections */}
                  <aside className="w-full sm:w-1/2 pl-0 sm:pl-16 pt-8 sm:pt-0 max-w-auto sm:max-w-[825px]">
                    {SECTIONS.map(({ key, label }) => {
                      const isOpen = openSection === key;
                      const isAbout = key === "about";
                      const hideHeader = isAbout && isOpen;
                      const content = getSectionContent(key);

                      return (
                        <div key={key} className="border-b border-DeepSea/40 last:border-b-0 mx-5">
                          {/* Section header */}
                          {!hideHeader && (
                            <button
                              onClick={() => handleSection(productId, key)}
                              aria-expanded={isOpen}
                              className="w-full flex justify-between items-center py-4 text-left group"
                            >
                              <span className="head-7 text-DeepSea font-bolder">{label}</span>
                              <PlusIcon isOpen={isOpen} className="text-DeepSea group-hover:opacity-60 transition-opacity" />
                            </button>
                          )}

                          {/* Section content */}
                          <AnimatePresence initial={false}>
                            {isOpen && (
                              <motion.div
                                key={`${productId}-${key}`}
                                initial="closed"
                                animate="open"
                                exit="closed"
                                variants={contentVariants}
                                className="overflow-hidden -ml-3 pl-3"
                              >
                                <div className={`body-4 text-DeepSea ${hideHeader ? "pt-2 pb-6" : "pb-6"}`}>
                                  {key === "about" ? (
                                    <div className="space-y-3">
                                      {(content as TextItem[]).map((item, idx) => (
                                        <p key={idx} dangerouslySetInnerHTML={{ __html: item.item ?? "" }} />
                                      ))}
                                      {(content as TextItem[]).length === 0 && (
                                        <p className="text-DeepSea/50 italic">Information coming soon.</p>
                                      )}
                                    </div>
                                  ) : key === "specifications" ? (
                                    <div className="">
                                      {(content as Spec[]).map((spec, idx) => (
                                        <React.Fragment key={idx}>
                                          {spec.subtitle && (
                                            <h3 className="body-4 text-DeepSea mt-8 mb-1 uppercase font-semibold">
                                              {spec.subtitle}
                                            </h3>
                                          )}
                                          {spec.item && (
                                            <p className="body-4" dangerouslySetInnerHTML={{ __html: spec.item }} />
                                          )}
                                        </React.Fragment>
                                      ))}
                                      {(content as Spec[]).length === 0 && (
                                        <p className="text-DeepSea/50 italic">Contact us for specifications.</p>
                                      )}
                                    </div>
                                  ) : (
                                    <ul className="list-none ">
                                      {(content as TextItem[]).map((item, idx) => (
                                        <React.Fragment key={idx}>
                                          {item.subtitle && (
                                            <h3 className="body-4 text-DeepSea mt-8 mb-1 uppercase ">
                                              {item.subtitle}
                                            </h3>
                                          )}
                                          {item.item && (
                                            <li className="relative before:content-['•'] before:absolute before:-left-3 before:top-0">
                                              <span dangerouslySetInnerHTML={{ __html: item.item }} />
                                              {item.items && item.items.length > 0 && (
                                                <ul className="">
                                                  {item.items.map((nested, nIdx) => (
                                                    <li
                                                      key={nIdx}
                                                      className="relative before:content-['•'] before:absolute before:-left-3 before:top-0 ml-6"
                                                      dangerouslySetInnerHTML={{ __html: nested.item }}
                                                    />
                                                  ))}
                                                </ul>
                                              )}
                                            </li>
                                          )}
                                        </React.Fragment>
                                      ))}
                                      {(content as TextItem[]).length === 0 && (
                                        <p className="text-DeepSea/50 italic">Information coming soon.</p>
                                      )}
                                    </ul>
                                  )}
                                </div>
                              </motion.div>
                            )}
                          </AnimatePresence>
                        </div>
                      );
                    })}
                  </aside>
                </div>

              </div>

            );
          })}
        </div>
      ))}
    </section>
  );
};

export default ProductDisplay;
